class BTSIPAddress(object):
    """Class to discover BTS IP addresses

    BTSIPAddress uses ARPScanner to discover following IP addresses:
        * FSM IP Address
        * TRS IP Address

    References:
        * https://jira3.int.net.nokia.com/browse/URW-2539
        * https://jira3.int.net.nokia.com/secure/attachment/256761/IPAddressSet.pdf
    """

    def __init__(self, posix=True, timeout=60):
        """
        :param boolean posix: Set library to work with Linux (True) or Windows (False).
        """
        self._posix = posix
        self._timeout = timeout

    def get_fsm_ip_address(self):
        """Method discovers available FSM IP address

        :return: First discovered FSM IP Address.
        :rtype: string
        """
        return '192.168.255.1'

    def get_trs_ip_address(self):
        """Method discovers available TRS IP address

        :return: First discovered TRS IP Address.
        :rtype: string
        """
        return '192.168.255.129'
